import{a as e,i as t,r as n,t as r}from"./app-DUb33vxN.js";var i=JSON.parse(`{"path":"/%E7%AC%AC13%E7%AB%A0%20%E9%A1%B9%E7%9B%AE%E8%B5%84%E6%BA%90%E7%AE%A1%E7%90%86/13.2%20%E5%9B%A2%E9%98%9F%E7%AE%A1%E7%90%86.html","title":"13.2 团队管理","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"第13章 项目资源管理/13.2 团队管理.md"}`),a={name:`13.2 团队管理.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="_13-2-团队管理" tabindex="-1"><a class="header-anchor" href="#_13-2-团队管理"><span>13.2 团队管理</span></a></h1><h2 id="定义" tabindex="-1"><a class="header-anchor" href="#定义"><span>定义</span></a></h2><p>团队管理是指管理项目团队，提高团队绩效，确保项目目标实现的过程。</p><h2 id="团队发展阶段" tabindex="-1"><a class="header-anchor" href="#团队发展阶段"><span>团队发展阶段</span></a></h2><h3 id="_1-形成阶段-forming" tabindex="-1"><a class="header-anchor" href="#_1-形成阶段-forming"><span>1. 形成阶段（Forming）</span></a></h3><ul><li><strong>特点</strong>：团队成员相互认识</li><li><strong>任务</strong>：建立团队规则和目标</li></ul><h3 id="_2-震荡阶段-storming" tabindex="-1"><a class="header-anchor" href="#_2-震荡阶段-storming"><span>2. 震荡阶段（Storming）</span></a></h3><ul><li><strong>特点</strong>：团队成员之间出现冲突</li><li><strong>任务</strong>：解决冲突，建立协作关系</li></ul><h3 id="_3-规范阶段-norming" tabindex="-1"><a class="header-anchor" href="#_3-规范阶段-norming"><span>3. 规范阶段（Norming）</span></a></h3><ul><li><strong>特点</strong>：团队成员开始协作</li><li><strong>任务</strong>：建立团队文化和规范</li></ul><h3 id="_4-执行阶段-performing" tabindex="-1"><a class="header-anchor" href="#_4-执行阶段-performing"><span>4. 执行阶段（Performing）</span></a></h3><ul><li><strong>特点</strong>：团队高效工作</li><li><strong>任务</strong>：专注于项目目标</li></ul><h3 id="_5-解散阶段-adjourning" tabindex="-1"><a class="header-anchor" href="#_5-解散阶段-adjourning"><span>5. 解散阶段（Adjourning）</span></a></h3><ul><li><strong>特点</strong>：项目结束，团队解散</li><li><strong>任务</strong>：总结经验，释放资源</li></ul><h2 id="团队建设方法" tabindex="-1"><a class="header-anchor" href="#团队建设方法"><span>团队建设方法</span></a></h2><h3 id="_1-团队培训" tabindex="-1"><a class="header-anchor" href="#_1-团队培训"><span>1. 团队培训</span></a></h3><ul><li><strong>内容</strong>：技术培训、软技能培训</li><li><strong>目的</strong>：提升团队能力</li></ul><h3 id="_2-团队活动" tabindex="-1"><a class="header-anchor" href="#_2-团队活动"><span>2. 团队活动</span></a></h3><ul><li><strong>类型</strong>：团队建设活动、社交活动</li><li><strong>目的</strong>：增强团队凝聚力</li></ul><h3 id="_3-激励机制" tabindex="-1"><a class="header-anchor" href="#_3-激励机制"><span>3. 激励机制</span></a></h3><ul><li><strong>方法</strong>：奖励制度、认可机制</li><li><strong>目的</strong>：提高团队积极性</li></ul><h3 id="_4-沟通管理" tabindex="-1"><a class="header-anchor" href="#_4-沟通管理"><span>4. 沟通管理</span></a></h3><ul><li><strong>方式</strong>：定期会议、沟通渠道</li><li><strong>目的</strong>：保持信息畅通</li></ul><h2 id="冲突管理" tabindex="-1"><a class="header-anchor" href="#冲突管理"><span>冲突管理</span></a></h2><h3 id="冲突类型" tabindex="-1"><a class="header-anchor" href="#冲突类型"><span>冲突类型</span></a></h3><ul><li><strong>人际冲突</strong>：团队成员之间的冲突</li><li><strong>任务冲突</strong>：关于任务分配的冲突</li><li><strong>资源冲突</strong>：资源分配的冲突</li></ul><h3 id="冲突管理策略" tabindex="-1"><a class="header-anchor" href="#冲突管理策略"><span>冲突管理策略</span></a></h3><ul><li><strong>回避</strong>：暂时避免冲突</li><li><strong>妥协</strong>：双方各让一步</li><li><strong>强制</strong>：一方强制另一方接受</li><li><strong>合作</strong>：寻求双赢解决方案</li><li><strong>缓和</strong>：强调共同利益</li></ul><h2 id="团队绩效评估" tabindex="-1"><a class="header-anchor" href="#团队绩效评估"><span>团队绩效评估</span></a></h2><h3 id="评估指标" tabindex="-1"><a class="header-anchor" href="#评估指标"><span>评估指标</span></a></h3><ul><li><strong>工作质量</strong>：完成工作的质量</li><li><strong>工作效率</strong>：完成工作的速度</li><li><strong>团队协作</strong>：团队合作情况</li><li><strong>目标达成</strong>：目标完成情况</li></ul><h3 id="评估方法" tabindex="-1"><a class="header-anchor" href="#评估方法"><span>评估方法</span></a></h3><ul><li><strong>定期评估</strong>：每周或每月评估</li><li><strong>360度评估</strong>：多方面反馈</li></ul><h2 id="关键考点" tabindex="-1"><a class="header-anchor" href="#关键考点"><span>关键考点</span></a></h2><ol><li><strong>团队发展阶段</strong></li><li><strong>冲突管理策略</strong></li><li><strong>团队建设方法</strong></li></ol><h2 id="记忆口诀" tabindex="-1"><a class="header-anchor" href="#记忆口诀"><span>记忆口诀</span></a></h2><p>团队建设五阶段，冲突管理要得当，建设方法多多样</p><h2 id="典型例题" tabindex="-1"><a class="header-anchor" href="#典型例题"><span>典型例题</span></a></h2><p><strong>例题</strong>：团队发展的哪个阶段会出现冲突？ A. 形成阶段 B. 震荡阶段 C. 规范阶段 D. 执行阶段</p><p><strong>答案</strong>：B</p><p><strong>解析</strong>：震荡阶段是团队成员之间开始出现冲突的阶段，需要解决冲突并建立协作关系。</p>`,41)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};